protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // EF Core 9: default discriminator property renamed from "Discriminator" to "$type".
        // Existing 500K documents use "Discriminator" — preserve it for data compatibility
        // and so direct SQL queries (c.Discriminator) continue to work.
        entity.HasDiscriminator<string>("Discriminator");

        // EF Core 9: id values no longer include the discriminator prefix.
        // Existing documents have id format "Product|123" — preserve it so
        // FindAsync and point-reads still resolve existing documents.
        entity.HasRootDiscriminatorInJsonId(true);
    });

    // EF Core 9: HasIndex now throws for Cosmos entities.
    // Removed HasIndex(p => p.Sku) — manage indexing via Azure Portal / Bicep / Terraform.
}

